/**
 * The settings screen (`design/archetypes/settings-page.md`).
 *
 * Generated by `pnpm shells` from `packages/shells/src/members/settings-page.ts`, the member's
 * framework-neutral description. Never edit it by hand: change the description and
 * run `pnpm shells`.
 */
import { Component, ViewEncapsulation, input } from '@angular/core'

import { MEMBER_PROVIDERS, SlotOutlet, SlotTemplate, useMember } from '@polymorph/angular'
import styles from '@polymorph/recipes/archetypes/settings-page.module.css'
import { PageHeader, type PageHeaderProps } from '../structure/PageHeader'

/** The settings screen: the inputs it takes, by the React member's prop names. */
export interface SettingsPageProps {
  description?: string
  title: string
}

/** The settings screen. */
@Component({
  selector: 'pm-settings-page',
  encapsulation: ViewEncapsulation.None,
  host: { style: 'display: contents' },
  providers: [...MEMBER_PROVIDERS],
  imports: [SlotOutlet, SlotTemplate, PageHeader],
  // prettier-ignore
  template: `<ng-template pmSlot="default" [pmSlotOf]="$"><ng-content /></ng-template>
<div
[attr.class]="e1()"
data-member="settings-page"
><pm-page-header
[title]="e2()"
[description]="e3()"
></pm-page-header>
<ng-container [pmSlotOutlet]="'default'" [pmSlotOf]="$" /></div>`,
})
export class SettingsPage {
  readonly description = input<SettingsPageProps['description']>(undefined)
  readonly title = input.required<SettingsPageProps['title']>()
  protected readonly $ = useMember({
    events: [],
    props: { description: () => this.description(), title: () => this.title() },
  })
  protected readonly $p = this.$.props

  protected e1() {
    return styles.page
  }

  protected e2(): PageHeaderProps['title'] {
    return this.$p.title
  }

  protected e3(): PageHeaderProps['description'] {
    return this.$p.description
  }
}
